//! Renders the generated `docs/traceability.md` report.
//!
//! The report is a header saying it is generated by `cargo xtask trace` and
//! must not be hand-edited, a one-line count summary, and a Markdown table
//! with one row per requirement line in `design.md`:
//!
//! | column | content |
//! |---|---|
//! | Requirement | the ID |
//! | ASIL | the tag, `untagged`, or `invalid: <text>` |
//! | Ticked | `yes` or `no` |
//! | Verifying tests | `path::fn` for each citing test, or `none` |
//! | Source files | the distinct files holding those tests, or `none` |
//!
//! Rows are sorted by ID then `design.md` line; tests by path, line and
//! name; files lexically. The output therefore depends only on the inputs'
//! content, never on file-system iteration order, and always ends with a
//! newline. Tests citing IDs not in `design.md` do not appear here; they are
//! reported as problems instead.

use std::collections::BTreeSet;

use super::{coverage, AsilTag, Requirement, Status, VerifyingTest};

/// Workspace-relative path of the generated report.
pub const REPORT_PATH: &str = "docs/traceability.md";

/// Renders the complete report text.
pub fn render(requirements: &[Requirement], tests: &[VerifyingTest]) -> String {
    let covered = coverage(tests);
    let mut rows: Vec<&Requirement> = requirements.iter().collect();
    rows.sort_by(|a, b| a.id.cmp(&b.id).then(a.line.cmp(&b.line)));

    let ticked = rows.iter().filter(|r| r.status == Status::Ticked).count();
    let verified = rows.iter().filter(|r| covered.contains_key(&r.id)).count();

    let mut out = String::new();
    out.push_str(
        "<!-- GENERATED FILE: do not edit by hand. Regenerate with `cargo xtask trace`. -->\n",
    );
    out.push_str("# Requirements Traceability\n\n");
    out.push_str(
        "Generated by `cargo xtask trace` from `design.md` and `/// Verifies:` tags on \
         `#[test]` functions. Do not hand-edit this file; `cargo xtask trace --check` fails \
         when it is out of date.\n\n",
    );
    out.push_str(&format!(
        "{} requirements, {ticked} ticked, {verified} with at least one verifying test.\n\n",
        rows.len()
    ));
    out.push_str("| Requirement | ASIL | Ticked | Verifying tests | Source files |\n");
    out.push_str("|---|---|---|---|---|\n");

    for req in rows {
        let citing = covered.get(&req.id).map_or(&[][..], Vec::as_slice);
        let tests_cell = join_or_none(citing.iter().map(|t| format!("`{}::{}`", t.path, t.name)));
        let files: BTreeSet<&str> = citing.iter().map(|t| t.path.as_str()).collect();
        let files_cell = join_or_none(files.iter().map(|f| format!("`{f}`")));
        let asil = match &req.asil {
            AsilTag::Valid(a) => a.label().to_owned(),
            AsilTag::Missing => "untagged".to_owned(),
            AsilTag::Invalid(t) => format!("invalid: {}", escape_cell(t)),
        };
        let ticked = match req.status {
            Status::Ticked => "yes",
            Status::Open => "no",
        };
        out.push_str(&format!(
            "| {} | {asil} | {ticked} | {tests_cell} | {files_cell} |\n",
            req.id
        ));
    }
    out
}

/// Joins cell entries with `<br>`, or returns `none` when there are none.
fn join_or_none(items: impl Iterator<Item = String>) -> String {
    let joined: Vec<String> = items.map(|s| escape_cell(&s)).collect();
    if joined.is_empty() {
        "none".to_owned()
    } else {
        joined.join("<br>")
    }
}

/// Escapes `|` so free text cannot break the table.
fn escape_cell(text: &str) -> String {
    text.replace('|', "\\|")
}

#[cfg(test)]
// Test code: panicking on a failed expectation is the point of a test.
#[cfg_attr(
    test,
    allow(
        clippy::unwrap_used,
        clippy::expect_used,
        clippy::indexing_slicing,
        clippy::panic
    )
)]
mod tests {
    use super::super::{requirements, stale_report_problem, tests_scan, Problem, ScanResult};
    use super::*;

    const DESIGN: &str = "\
- [x] **REQ-B-2** [ASIL B]: second
- [ ] **REQ-A-1**: first, untagged
- [x] **REQ-C-3** [ASIL X|Y]: odd tag
";

    const SRC_A: &str = "\
/// Verifies: REQ-B-2
#[test]
fn zeta() {}

/// Verifies: REQ-B-2, REQ-A-1
#[test]
fn alpha() {}
";

    const SRC_B: &str = "\
/// Verifies: REQ-B-2
#[test]
fn beta() {}
";

    fn build(order_ab: bool) -> String {
        let (reqs, _) = requirements::parse(DESIGN);
        let a = tests_scan::scan("m/a.rs", SRC_A);
        let b = tests_scan::scan("m/b.rs", SRC_B);
        let scan: ScanResult = if order_ab { a.merge(b) } else { b.merge(a) };
        render(&reqs, &scan.tests)
    }

    #[test]
    fn renders_header_and_sorted_rows() {
        let text = build(true);
        let expected = "\
<!-- GENERATED FILE: do not edit by hand. Regenerate with `cargo xtask trace`. -->
# Requirements Traceability

Generated by `cargo xtask trace` from `design.md` and `/// Verifies:` tags on `#[test]` functions. Do not hand-edit this file; `cargo xtask trace --check` fails when it is out of date.

3 requirements, 2 ticked, 2 with at least one verifying test.

| Requirement | ASIL | Ticked | Verifying tests | Source files |
|---|---|---|---|---|
| REQ-A-1 | untagged | no | `m/a.rs::alpha` | `m/a.rs` |
| REQ-B-2 | ASIL B | yes | `m/a.rs::zeta`<br>`m/a.rs::alpha`<br>`m/b.rs::beta` | `m/a.rs`<br>`m/b.rs` |
| REQ-C-3 | invalid: ASIL X\\|Y | yes | none | none |
";
        assert_eq!(text, expected);
    }

    #[test]
    fn rendering_is_independent_of_scan_order() {
        assert_eq!(build(true), build(false));
    }

    #[test]
    fn stale_report_is_detected_against_rendered_text() {
        let fresh = build(true);
        assert_eq!(
            stale_report_problem(REPORT_PATH, Some(&fresh), &fresh),
            None
        );
        let edited = fresh.replace("none", "hand-edited");
        assert_eq!(
            stale_report_problem(REPORT_PATH, Some(&edited), &fresh),
            Some(Problem::StaleReport {
                path: REPORT_PATH.to_owned()
            })
        );
    }
}
